//go:build linux

package client

import (
	"errors"
	"net/url"
)

const chatGPTUsageURL = "https://chatgpt.com/settings/usage"

var errAccountBrowserUnavailable = errors.New("client: native account browser unavailable")

// openChatGPTAuthorization is called only by an explicit sign-in action. The
// callback URL is generated by Blur's OAuth transaction.
func openChatGPTAuthorization(raw string) error {
	if !validChatGPTAuthorizationURL(raw) {
		return errAccountBrowserUnavailable
	}
	return openAccountBrowserURL(raw)
}

func openChatGPTUsage() error { return openAccountBrowserURL(chatGPTUsageURL) }

func openAccountBrowserURL(raw string) error {
	app, err := currentDesktopApp()
	if err != nil {
		return errAccountBrowserUnavailable
	}
	if err := app.OpenURL(raw); err != nil {
		return errAccountBrowserUnavailable
	}
	return nil
}

// validChatGPTAuthorizationURL accepts only the OpenAI authorization endpoint,
// matching the macOS account browser's check.
func validChatGPTAuthorizationURL(raw string) bool {
	u, err := url.Parse(raw)
	return err == nil && len(raw) <= 8192 && u.Scheme == "https" && u.Host == "auth.openai.com" && u.Path == "/api/accounts/authorize" && u.RawPath == "" && u.User == nil && u.Fragment == "" && u.Opaque == ""
}
